We need to be careful about variable naming conflict: we have output variable leadPump, also static variable prevLeadPump. That's fine.

Now implement:

- Clip demand: effectiveDemand := MIN(5, MAX(0, demand));

- runningCount := effectiveDemand.

- If effectiveDemand = 0 then
    leadPump := 0;
    lagPump := 0;
    // clear prev? Not necessary but we can set prevLeadPump etc for next cycle? We could set them but not needed.
    // But we need to update prev values for next cycle? Let's just update prevLeadPump := leadPump; same for lagPump and runningCount.
    prevLeadPump := leadPump;
    prevLagPump := lagPump;
    prevRunningCount := runningCount;
    return; // or continue to end.
 else
    // effectiveDemand > 0
    // Determine if initial selection needed:
    if leadPump = 0 then
        // initial selection: find pump with min runHours (tie smallest index)
        // We'll use a helper function to find min index.
        // Implement manually:
        minHours := runHours[1];
        minIndex := 1;
        for i := 2 to 5 do
            if runHours[i] < minHours OR (runHours[i] = minHours AND i < minIndex) then
                minHours := runHours[i];
                minIndex := i;
            end_if;
        end_for;
        leadPump := minIndex;

        // compute lagPump if needed
        if effectiveDemand >= 2 then
            // find min among others
            // We need to find min among i != leadPump.
            // Initialize with a large number.
            lagMinHours := LINT#MAX;
            lagMinIndex := 0;
            for i := 1 to 5 do
                if i <> leadPump then
                    if runHours[i] < lagMinHours OR (runHours[i] = lagMinHours AND i < lagMinIndex) then
                        lagMinHours := runHours[i];
                        lagMinIndex := i;
                    end_if;
                end_if;
            end_for;
            lagPump := lagMinIndex;
        else
            lagPump := 0;
        end_if;
    else
        // leadPump already selected
        // handle rotation request
        if rotated then
            // compute global min
            minHours := runHours[1];
            minIndex := 1;
            for i := 2 to 5 do
                if runHours[i] < minHours OR (runHours[i] = minHours AND i < minIndex) then
                    minHours := runHours[i];
                    minIndex := i;
                end_if;
            end_for;
            // check difference > 50
            if runHours[leadPump] - minHours > 50 then
